/// <summary>
/// Controller class for Sales Invoice Dual Write Update abtch job.
/// </summary>
public class METSalesInvoiceDualWriteUpdateController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Creates a new instance of the <c>METSalesInvoiceDualWriteUpdateController</c> class.
/// </summary>
protected void new()
{
    super(classStr(METSalesInvoiceDualWriteUpdateService), methodStr(METSalesInvoiceDualWriteUpdateService, process), SysOperationExecutionMode::Synchronous);
}

public static METSalesInvoiceDualWriteUpdateController construct()
{
    return new METSalesInvoiceDualWriteUpdateController();
}

/// <summary>
/// Executes the batch job.
/// </summary>
public static void main(Args _args)
{
    METSalesInvoiceDualWriteUpdateController controller = METSalesInvoiceDualWriteUpdateController::construct();
    controller.parmArgs(_args);

    // Starts operation, displaying the dialog with the "Batch" tab available
    controller.startOperation();
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "@MET:SalesInvoiceDualWriteUpdate";
}

/// <summary>
/// Validates the configuration for the Sales Invoice Dual Write Update batch job.
/// Ensures that the required parameter <c>METSODWSingleCommitCount</c> is configured.
/// </summary>
protected boolean validate()
{
    CustParameters      custParameters = CustParameters::find();
    boolean             isValid = super();

    if (isValid
        && custParameters.METSOInvoiceJobRecordCommitCount < 1)
    {          
        isValid = checkFailed("@MET:SOInvoiceJobCommitCountWarning");
    }

    return isValid;
}
